fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    // Try to parse as plain number
    if let Ok(n) = s.parse::<u64>() {
        return Some(n);
    }
    // Try human-readable formats: KB, MB, GB, KiB, MiB, GiB
    let s_upper = s.to_uppercase();
    let (num_str, unit) = if s_upper.ends_with("KIB") {
        (&s[..s.len()-3], 1024u64)
    } else if s_upper.ends_with("MIB") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s_upper.ends_with("GIB") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s_upper.ends_with("KB") {
        (&s[..s.len()-2], 1000u64)
    } else if s_upper.ends_with("MB") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s_upper.ends_with("GB") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else if s_upper.ends_with("K") {
        (&s[..s.len()-1], 1000u64)
    } else if s_upper.ends_with("M") {
        (&s[..s.len()-1], 1000 * 1000)
    } else if s_upper.ends_with("G") {
        (&s[..s.len()-1], 1000 * 1000 * 1000)
    } else {
        return None;
    };
    if let Ok(n) = num_str.trim().parse::<f64>() {
        Some((n * unit as f64) as u64)
    } else {
        None
    }
}

fn parse_min_savings(s: &str) -> Option<MinSavings> {
    let s = s.trim();
    if s.ends_with('%') {
        if let Ok(n) = s[..s.len()-1].parse::<f64>() {
            return Some(MinSavings::Percentage(n));
        }
    }
    if let Some(bytes) = parse_size(s) {
        return Some(MinSavings::Bytes(bytes));
    }
    None
}

#[derive(Debug, Clone)]
enum MinSavings {
    Percentage(f64),
    Bytes(u64),
}

fn format_size(bytes: u64) -> String {
    if bytes >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    } else if bytes >= 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else if bytes >= 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{} B", bytes)
    }
}

fn format_size_diff(diff_bytes: i64) -> String {
    let abs = diff_bytes.unsigned_abs();
    if abs >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB", abs as f64 / (1024.0 * 1024.0 * 1024.0))
    } else if abs >= 1024 * 1024 {
        format!("{:.1} MiB", abs as f64 / (1024.0 * 1024.0))
    } else if abs >= 1024 {
        format!("{:.1} KiB", abs as f64 / 1024.0)
    } else {
        format!("{} B", abs)
    }
}

fn is_supported_image(path: &Path) -> bool {
    let ext = path.extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_lowercase())
        .unwrap_or_default();
    matches!(ext.as_str(), "jpg" | "jpeg" | "png" | "webp" | "gif")
}

fn get_output_extension(format: &OutputFormat, original_path: &Path) -> String {
    match format {
        OutputFormat::Jpeg => "jpg".to_string(),
        OutputFormat::Png => "png".to_string(),
        OutputFormat::Gif => "gif".to_string(),
        OutputFormat::Webp => "webp".to_string(),
        OutputFormat::Tiff => "tiff".to_string(),
        OutputFormat::Original => {
            original_path.extension()
                .and_then(|e| e.to_str())
                .unwrap_or("jpg")
                .to_string()
        }
    }
}

