fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    // Try to parse as plain number
    if let Ok(n) = s.parse::<u64>() {
        return Some(n);
    }
    // Try human-readable formats: KB, MB, GB, KiB, MiB, GiB
    let s_upper = s.to_uppercase();
    let (num_str, unit) = if s_upper.ends_with("KIB") {
        (&s[..s.len()-3], 1024u64)
    } else if s_upper.ends_with("MIB") {
        (&s[..s.len()-3], 1024 * 1024)
    } else if s_upper.ends_with("GIB") {
        (&s[..s.len()-3], 1024 * 1024 * 1024)
    } else if s_upper.ends_with("KB") {
        (&s[..s.len()-2], 1000u64)
    } else if s_upper.ends_with("MB") {
        (&s[..s.len()-2], 1000 * 1000)
    } else if s_upper.ends_with("GB") {
        (&s[..s.len()-2], 1000 * 1000 * 1000)
    } else if s_upper.ends_with("K") {
        (&s[..s.len()-1], 1000u64)
    } else if s_upper.ends_with("M") {
        (&s[..s.len()-1], 1000 * 1000)
    } else if s_upper.ends_with("G") {
        (&s[..s.len()-1], 1000 * 1000 * 1000)
    } else {
        return None;
    };
    if let Ok(n) = num_str.trim().parse::<f64>() {
        Some((n * unit as f64) as u64)
    } else {
        None
    }
}

fn parse_min_savings(s: &str) -> Option<MinSavings> {
    let s = s.trim();
    if s.ends_with('%') {
        if let Ok(n) = s[..s.len()-1].parse::<f64>() {
            return Some(MinSavings::Percentage(n));
        }
    }
    if let Some(bytes) = parse_size(s) {
        return Some(MinSavings::Bytes(bytes));
    }
    None
}

#[derive(Debug, Clone)]
enum MinSavings {
    Percentage(f64),
    Bytes(u64),
}

fn format_size(bytes: u64) -> String {
    if bytes >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
    } else if bytes >= 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else if bytes >= 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{} B", bytes)
    }
}

fn format_size_diff(diff_bytes: i64) -> String {
    let abs = diff_bytes.unsigned_abs();
    if abs >= 1024 * 1024 * 1024 {
        format!("{:.1} GiB", abs as f64 / (1024.0 * 1024.0 * 1024.0))
    } else if abs >= 1024 * 1024 {
        format!("{:.1} MiB", abs as f64 / (1024.0 * 1024.0))
    } else if abs >= 1024 {
        format!("{:.1} KiB", abs as f64 / 1024.0)
    } else {
        format!("{} B", abs)
    }
}

fn is_supported_image(path: &Path) -> bool {
    let ext = path.extension()
        .and_then(|e| e.to_str())
        .map(|e| e.to_lowercase())
        .unwrap_or_default();
    matches!(ext.as_str(), "jpg" | "jpeg" | "png" | "webp" | "gif")
}

fn get_output_extension(format: &OutputFormat, original_path: &Path) -> String {
    match format {
        OutputFormat::Jpeg => "jpg".to_string(),
        OutputFormat::Png => "png".to_string(),
        OutputFormat::Gif => "gif".to_string(),
        OutputFormat::Webp => "webp".to_string(),
        OutputFormat::Tiff => "tiff".to_string(),
        OutputFormat::Original => {
            original_path.extension()
                .and_then(|e| e.to_str())
                .unwrap_or("jpg")
                .to_string()
        }
    }
}

#[derive(Debug)]
enum CompressionResult {
    Success {
        input_size: u64,
        output_size: u64,
    },
    Skipped {
        input_size: u64,
        reason: String,
    },
    Error {
        message: String,
    },
}

struct ProcessTask {
    input: PathBuf,
    output: PathBuf,
}

fn collect_files(inputs: &[PathBuf], recursive: bool) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for input in inputs {
        if input.is_dir() {
            let walker = if recursive {
                WalkDir::new(input).max_depth(usize::MAX)
            } else {
                WalkDir::new(input).max_depth(1)
            };
            for entry in walker.into_iter().filter_map(|e| e.ok()) {
                if entry.file_type().is_file() && is_supported_image(entry.path()) {
                    files.push(entry.path().to_path_buf());
                }
            }
        } else if input.is_file() {
            if is_supported_image(input) {
                files.push(input.clone());
            }
        }
    }
    files
}

fn compute_base_path(files: &[PathBuf]) -> Option<PathBuf> {
    if files.is_empty() {
        return None;
    }
    if files.len() == 1 {
        return files[0].parent().map(|p| p.to_path_buf());
    }
    // Find common prefix
    let paths: Vec<&Path> = files.iter().map(|f| f.as_path()).collect();
    let first_components: Vec<_> = paths[0].components().collect();
    let mut common_len = first_components.len();
    for path in &paths[1..] {
        let comps: Vec<_> = path.components().collect();
        let matching = first_components.iter().zip(comps.iter())
            .take_while(|(a, b)| a == b)
            .count();
        common_len = common_len.min(matching);
    }
    if common_len == 0 {
        return Some(PathBuf::from("/"));
    }
    let mut result = PathBuf::new();
    for comp in &first_components[..common_len] {
        result.push(comp);
    }
    Some(result)
}

fn determine_output_path(
    input: &Path,
    base_path: &Path,
    output_dir: Option<&Path>,
    same_folder_as_input: bool,
    keep_structure: bool,
    suffix: Option<&str>,
    format: &OutputFormat,
) -> PathBuf {
    let stem = input.file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("output");
    let ext = get_output_extension(format, input);

    let filename = if let Some(s) = suffix {
        format!("{}{}.{}", stem, s, ext)
    } else {
        format!("{}.{}", stem, ext)
    };

    if same_folder_as_input {
        let parent = input.parent().unwrap_or(Path::new("."));
        return parent.join(&filename);
    }

    if let Some(out_dir) = output_dir {
        if keep_structure {
            // Preserve relative structure from base_path
            if let Ok(rel) = input.strip_prefix(base_path) {
                let rel_parent = rel.parent().unwrap_or(Path::new(""));
                return out_dir.join(rel_parent).join(&filename);
            }
        }
        return out_dir.join(&filename);
    }

    PathBuf::from(&filename)
}

fn compress_jpeg(
    input_data: &[u8],
    quality: u32,
    lossless: bool,
    exif_data: Option<Vec<u8>>,
    baseline: bool,
    chroma_subsampling: &ChromaSubsampling,
    strip_icc: bool,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    if lossless {
        // For lossless JPEG, use mozjpeg with quality 100
        compress_jpeg_mozjpeg(input_data, 100, exif_data, baseline, chroma_subsampling, strip_icc)
    } else {
        compress_jpeg_mozjpeg(input_data, quality, exif_data, baseline, chroma_subsampling, strip_icc)
    }
}

fn compress_jpeg_mozjpeg(
    input_data: &[u8],
    quality: u32,
    exif_data: Option<Vec<u8>>,
    baseline: bool,
    chroma_subsampling: &ChromaSubsampling,
    _strip_icc: bool,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    use mozjpeg::{Compress, ColorSpace, ScanMode};

    // Decode first using image crate
    let img = image::load_from_memory(input_data)?;
    let rgb = img.to_rgb8();
    let (width, height) = rgb.dimensions();

    let mut comp = Compress::new(ColorSpace::JCS_RGB);
    comp.set_size(width as usize, height as usize);
    comp.set_quality(quality as f32);

    if baseline {
        comp.set_scan_optimization_mode(ScanMode::AllComponentsTogether);
    } else {
        comp.set_scan_optimization_mode(ScanMode::Auto);
    }

    let cs = match chroma_subsampling {
        ChromaSubsampling::S444 => mozjpeg::qtable::AnnexKHVS,
        _ => mozjpeg::qtable::AnnexKHVS,
    };

    let mut started = comp.start_compress(Vec::new())?;
    started.write_scan(rgb.as_raw())?;
    let mut result = started.finish()?;

    // Append EXIF data if needed
    if let Some(exif) = exif_data {
        // Insert EXIF data into JPEG
        // EXIF goes into APP1 marker after SOI
        if result.len() > 2 && exif.len() > 0 {
            let mut new_result = Vec::new();
            new_result.extend_from_slice(&result[..2]); // SOI
            // APP1 marker
            let exif_len = exif.len() + 2;
            new_result.push(0xFF);
            new_result.push(0xE1);
            new_result.push((exif_len >> 8) as u8);
            new_result.push((exif_len & 0xFF) as u8);
            new_result.extend_from_slice(&exif);
            new_result.extend_from_slice(&result[2..]);
            result = new_result;
        }
    }

    Ok(result)
}

fn compress_png(
    input_data: &[u8],
    quality: Option<u32>,
    lossless: bool,
    opt_level: u8,
    use_zopfli: bool,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    use oxipng::{Options, optimize_from_memory};

    let input_for_oxipng = if !lossless {
        // First do lossy compression with imagequant
        if let Some(q) = quality {
            compress_png_lossy(input_data, q)?
        } else {
            input_data.to_vec()
        }
    } else {
        input_data.to_vec()
    };

    let mut options = Options::default();
    options.optimize_alpha = true;

    // Set optimization level
    let level = opt_level.min(6);
    options = match level {
        0 => Options::from_preset(0),
        1 => Options::from_preset(1),
        2 => Options::from_preset(2),
        3 => Options::from_preset(3),
        4 => Options::from_preset(4),
        5 => Options::from_preset(5),
        _ => Options::from_preset(6),
    };

    if use_zopfli {
        options.deflate = oxipng::Deflaters::Zopfli { iterations: std::num::NonZeroU8::new(15).unwrap() };
    }

    let result = optimize_from_memory(&input_for_oxipng, &options)
        .map_err(|e| format!("PNG optimization error: {}", e))?;

    Ok(result)
}

fn compress_png_lossy(
    input_data: &[u8],
    quality: u32,
    ) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    use image::{DynamicImage, ImageOutputFormat};

    let img = image::load_from_memory(input_data)?;
    let rgba = img.to_rgba8();
    let (width, height) = rgba.dimensions();

    // Use imagequant for lossy PNG
    let mut liq = imagequant::new();
    let q = (quality as f64 / 100.0 * 100.0) as u8;
    liq.set_quality(0, q).map_err(|e| format!("{:?}", e))?;

    let mut image = liq.new_image(
        rgba.as_raw().as_slice(),
        width as usize,
        height as usize,
        0.0,
    ).map_err(|e| format!("{:?}", e))?;

    let mut res = liq.quantize(&mut image).map_err(|e| format!("{:?}", e))?;
    res.set_dithering_level(1.0).map_err(|e| format!("{:?}", e))?;

    let (palette, pixels) = res.remapped(&mut image).map_err(|e| format!("{:?}", e))?;

    // Encode as PNG
    let mut encoder = png::Encoder::new(Vec::new(), width, height);
    encoder.set_color(png::ColorType::Indexed);
    encoder.set_depth(png::BitDepth::Eight);

    // Set palette
    let palette_bytes: Vec<u8> = palette.iter().flat_map(|c| [c.r, c.g, c.b]).collect();
    let alpha_bytes: Vec<u8> = palette.iter().map(|c| c.a).collect();
    encoder.set_palette(palette_bytes);
    encoder.set_trns(alpha_bytes);

    let mut writer = encoder.write_header()?;
    writer.write_image_data(&pixels)?;
    let buf = writer.finish()?;

    Ok(buf)
}

fn compress_webp(
    input_data: &[u8],
    quality: u32,
    lossless: bool,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    let img = image::load_from_memory(input_data)?;

    let result = if lossless {
        let rgba = img.to_rgba8();
        webp::Encoder::from_rgba(rgba.as_raw(), rgba.width(), rgba.height())
            .encode_lossless()
            .to_vec()
    } else {
        let rgb = img.to_rgb8();
        webp::Encoder::from_rgb(rgb.as_raw(), rgb.width(), rgb.height())
            .encode(quality as f32)
            .to_vec()
    };

    Ok(result)
}

fn compress_gif(
    input_data: &[u8],
    quality: u32,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    // For GIF, use the image crate for re-encoding
    use image::codecs::gif::{GifEncoder, Repeat};
    use image::AnimationDecoder;

    let cursor = std::io::Cursor::new(input_data);
    let decoder = image::codecs::gif::GifDecoder::new(cursor)?;
    let frames: Vec<_> = decoder.into_frames().collect_frames()?;

    let mut output = Vec::new();
    {
        let mut encoder = GifEncoder::new_with_speed(&mut output, (10 - quality / 10).max(1) as i32);
        encoder.set_repeat(Repeat::Infinite)?;
        for frame in frames {
            encoder.encode_frame(frame)?;
        }
    }

    Ok(output)
}

fn resize_image(
    img: image::DynamicImage,
    width: Option<u32>,
    height: Option<u32>,
    long_edge: Option<u32>,
    short_edge: Option<u32>,
    no_upscale: bool,
) -> image::DynamicImage {
    let (orig_width, orig_height) = (img.width(), img.height());

    let (new_width, new_height) = if let Some(le) = long_edge {
        let is_landscape = orig_width >= orig_height;
        if is_landscape {
            let h = (le as f64 * orig_height as f64 / orig_width as f64).round() as u32;
            (le, h)
        } else {
            let w = (le as f64 * orig_width as f64 / orig_height as f64).round() as u32;
            (w, le)
        }
    } else if let Some(se) = short_edge {
        let is_landscape = orig_width >= orig_height;
        if is_landscape {
            let w = (se as f64 * orig_width as f64 / orig_height as f64).round() as u32;
            (w, se)
        } else {
            let h = (se as f64 * orig_height as f64 / orig_width as f64).round() as u32;
            (se, h)
        }
    } else if let (Some(w), Some(h)) = (width, height) {
        (w, h)
    } else if let Some(w) = width {
        let h = (w as f64 * orig_height as f64 / orig_width as f64).round() as u32;
        (w, h.max(1))
    } else if let Some(h) = height {
        let w = (h as f64 * orig_width as f64 / orig_height as f64).round() as u32;
        (w.max(1), h)
    } else {
        return img;
    };

    if no_upscale {
        if new_width > orig_width || new_height > orig_height {
            return img;
        }
    }

    img.resize(new_width, new_height, image::imageops::FilterType::Lanczos3)
}

fn get_exif_data(input_data: &[u8]) -> Option<Vec<u8>> {
    // Find EXIF data in JPEG
    let mut i = 0;
    if input_data.len() < 2 || input_data[0] != 0xFF || input_data[1] != 0xD8 {
        return None;
    }
    i = 2;
    while i + 3 < input_data.len() {
        if input_data[i] != 0xFF {
            break;
        }
        let marker = input_data[i + 1];
        if marker == 0xE1 {
            // APP1 - EXIF
            let len = ((input_data[i + 2] as usize) << 8) | (input_data[i + 3] as usize);
            if i + 2 + len <= input_data.len() {
                return Some(input_data[i + 4..i + 2 + len].to_vec());
            }
        }
        let len = ((input_data[i + 2] as usize) << 8) | (input_data[i + 3] as usize);
        i += 2 + len;
    }
    None
}

fn compress_to_max_size(
    input_data: &[u8],
    input_path: &Path,
    target_size: u64,
    args: &Args,
    format: &OutputFormat,
) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    let ext = get_effective_format(input_path, format);

    let mut low = 1u32;
    let mut high = 100u32;
    let mut best = Vec::new();

    // Binary search for quality
    while low <= high {
        let mid = (low + high) / 2;
        let result = match ext.as_str() {
            "jpeg" | "jpg" => compress_jpeg(input_data, mid, false, None, args.jpeg_baseline, &args.jpeg_chroma_subsampling, args.strip_icc),
            "png" => compress_png(input_data, Some(mid), false, args.png_opt_level, args.zopfli),
            "webp" => compress_webp(input_data, mid, false),
            "gif" => compress_gif(input_data, mid),
            _ => compress_jpeg(input_data, mid, false, None, args.jpeg_baseline, &args.jpeg_chroma_subsampling, args.strip_icc),
        }?;

        if result.len() as u64 <= target_size {
            best = result;
            low = mid + 1;
        } else {
            if mid == 0 {
                break;
            }
            high = mid - 1;
        }
    }

    if best.is_empty() {
        // Use lowest quality
        let result = match ext.as_str() {
            "jpeg" | "jpg" => compress_jpeg(input_data, 1, false, None, args.jpeg_baseline, &args.jpeg_chroma_subsampling, args.strip_icc),
            "png" => compress_png(input_data, Some(1), false, args.png_opt_level, args.zopfli),
            "webp" => compress_webp(input_data, 1, false),
            "gif" => compress_gif(input_data, 1),
            _ => compress_jpeg(input_data, 1, false, None, args.jpeg_baseline, &args.jpeg_chroma_subsampling, args.strip_icc),
        }?;
        best = result;
    }

    Ok(best)
}

fn get_effective_format(input_path: &Path, format: &OutputFormat) -> String {
    match format {
        OutputFormat::Jpeg => "jpg".to_string(),
        OutputFormat::Png => "png".to_string(),
        OutputFormat::Gif => "gif".to_string(),
        OutputFormat::Webp => "webp".to_string(),
        OutputFormat::Tiff => "tiff".to_string(),
        OutputFormat::Original => {
            input_path.extension()
                .and_then(|e| e.to_str())
                .map(|e| e.to_lowercase())
                .unwrap_or_else(|| "jpg".to_string())
        }
    }
}

fn process_single_file(
    input: &Path,
    output: &Path,
    args: &Args,
) -> CompressionResult {
    // Read input file
    let input_data = match fs::read(input) {
        Ok(d) => d,
        Err(e) => return CompressionResult::Error { message: format!("Failed to read {}: {}", input.display(), e) },
    };
    let input_size = input_data.len() as u64;

    // Check overwrite policy (before processing)
    if !args.dry_run && output.exists() {
        match args.overwrite {
            OverwritePolicy::Never => {
                return CompressionResult::Skipped {
                    input_size,
                    reason: "File already exists, skipped due overwrite policy".to_string(),
                };
            }
            OverwritePolicy::Bigger => {
                let existing_size = fs::metadata(output).map(|m| m.len()).unwrap_or(0);
                // Only overwrite if existing > compressed output
                // We need to compress first... actually this check is done after compression
                // Let me rethink: we need to do partial processing
            }
            OverwritePolicy::All => {}
        }
    }

    // Apply resizing if needed
    let data_for_compress = if args.width.is_some() || args.height.is_some() || args.long_edge.is_some() || args.short_edge.is_some() {
        match resize_input(&input_data, input, args) {
            Ok(d) => d,
            Err(e) => return CompressionResult::Error { message: format!("Failed to resize {}: {}", input.display(), e) },
        }
    } else {
        input_data.clone()
    };

    // Get EXIF data if needed
    let exif_data = if args.exif {
        get_exif_data(&input_data)
    } else {
        None
    };

    let effective_format = get_effective_format(input, &args.format);

    // Compress
    let compressed = if let Some(ref max_size_str) = args.max_size {
        let target = match parse_size(max_size_str) {
            Some(s) => s,
            None => return CompressionResult::Error { message: format!("Invalid max-size: {}", max_size_str) },
        };
        match compress_to_max_size(&data_for_compress, input, target, args, &args.format) {
            Ok(d) => d,
            Err(e) => return CompressionResult::Error { message: format!("Failed to compress {}: {}", input.display(), e) },
        }
    } else {
        let result = match effective_format.as_str() {
            "jpg" | "jpeg" => compress_jpeg(
                &data_for_compress,
                args.quality.unwrap_or(80),
                args.lossless,
                exif_data,
                args.jpeg_baseline,
                &args.jpeg_chroma_subsampling,
                args.strip_icc,
            ),
            "png" => compress_png(
                &data_for_compress,
                args.quality,
                args.lossless,
                args.png_opt_level,
                args.zopfli,
            ),
            "webp" => compress_webp(
                &data_for_compress,
                args.quality.unwrap_or(80),
                args.lossless,
            ),
            "gif" => compress_gif(
                &data_for_compress,
                args.quality.unwrap_or(80),
            ),
            "tiff" => compress_to_tiff(&data_for_compress),
            _ => return CompressionResult::Error { message: format!("Unsupported format: {}", effective_format) },
        };
        match result {
            Ok(d) => d,
            Err(e) => return CompressionResult::Error { message: format!("Failed to compress {}: {}", input.display(), e) },
        }
    };

    let output_size = compressed.len() as u64;

    if args.dry_run {
        return CompressionResult::Success { input_size, output_size: input_size };
    }

    // Check overwrite "bigger" policy after compression
    if output.exists() {
        match args.overwrite {
            OverwritePolicy::Bigger => {
                let existing_size = fs::metadata(output).map(|m| m.len()).unwrap_or(0);
                if existing_size <= output_size {
                    return CompressionResult::Skipped {
                        input_size,
                        reason: "File already exists, skipped due overwrite policy".to_string(),
                    };
                }
            }
            _ => {}
        }
    }

    // Check min-savings
    if let Some(ref min_savings_str) = args.min_savings {
        let min_savings = match parse_min_savings(min_savings_str) {
            Some(s) => s,
            None => return CompressionResult::Error { message: format!("Invalid min-savings: {}", min_savings_str) },
        };

        let savings_ok = match &min_savings {
            MinSavings::Percentage(pct) => {
                if input_size == 0 {
                    true
                } else {
                    let actual_savings = (input_size as f64 - output_size as f64) / input_size as f64 * 100.0;
                    actual_savings >= *pct
                }
            }
            MinSavings::Bytes(bytes) => {
                if input_size < output_size {
                    false
                } else {
                    (input_size - output_size) >= *bytes
                }
            }
        };

        if !savings_ok {
            let reason = match &min_savings {
                MinSavings::Percentage(pct) => {
                    let actual_savings = if input_size == 0 { 0.0 } else {
                        (input_size as f64 - output_size as f64) / input_size as f64 * 100.0
                    };
                    format!("Insufficient savings: {:.2}% < {:.2}%, skipped", actual_savings, pct)
                }
                MinSavings::Bytes(bytes) => {
                    let actual_savings = if input_size >= output_size { input_size - output_size } else { 0 };
                    format!("Insufficient savings: {} < {}, skipped", 
                        format_size(actual_savings),
                        format_size(*bytes))
                }
            };
            return CompressionResult::Skipped { input_size, reason };
        }
    }

    // Write output
    if let Some(parent) = output.parent() {
        if let Err(e) = fs::create_dir_all(parent) {
            return CompressionResult::Error { message: format!("Failed to create output dir: {}", e) };
        }
    }

    if let Err(e) = fs::write(output, &compressed) {
        return CompressionResult::Error { message: format!("Failed to write {}: {}", output.display(), e) };
    }

    // Keep dates if requested
    if args.keep_dates {
        if let Ok(metadata) = fs::metadata(input) {
            let _ = filetime::set_file_times(
                output,
                filetime::FileTime::from_last_access_time(&metadata),
                filetime::FileTime::from_last_modification_time(&metadata),
            );
        }
    }

    CompressionResult::Success { input_size, output_size }
}

fn resize_input(input_data: &[u8], input_path: &Path, args: &Args) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    let img = image::load_from_memory(input_data)?;
    let resized = resize_image(img, args.width, args.height, args.long_edge, args.short_edge, args.no_upscale);

    let mut buf = Vec::new();
    let ext = get_effective_format(input_path, &args.format);
    match ext.as_str() {
        "jpg" | "jpeg" => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Jpeg)?,
        "png" => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Png)?,
        "webp" => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::WebP)?,
        "gif" => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Gif)?,
        "tiff" => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Tiff)?,
        _ => resized.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Jpeg)?,
    }

    Ok(buf)
}

fn compress_to_tiff(input_data: &[u8]) -> Result<Vec<u8>, Box<dyn std::error::Error + Send + Sync>> {
    let img = image::load_from_memory(input_data)?;
    let mut buf = Vec::new();
    img.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Tiff)?;
    Ok(buf)
}

fn main() {
    let args = Args::parse();

    let verbose = if args.quiet { 0 } else { args.verbose };

    // Set thread count
    if args.threads > 0 {
        rayon::ThreadPoolBuilder::new()
            .num_threads(args.threads)
            .build_global()
            .ok();
    }

    // Collect files
    let all_files = collect_files(&args.files, args.recursive);

    if all_files.is_empty() {
        eprintln!("Unable to compute the base path for the files.");
        std::process::exit(255);
    }

    // Compute base path for keep-structure
    let base_path = match compute_base_path(&all_files) {
        Some(p) => p,
        None => {
            eprintln!("Unable to compute the base path for the files.");
            std::process::exit(255);
        }
    };

    // Build task list
    let tasks: Vec<ProcessTask> = all_files.iter().map(|input| {
        let output = determine_output_path(
            input,
            &base_path,
            args.output.as_deref(),
            args.same_folder_as_input,
            args.keep_structure,
            args.suffix.as_deref(),
            &args.format,
        );
        ProcessTask {
            input: input.clone(),
            output,
        }
    }).collect();

    let total_input_size = Arc::new(Mutex::new(0u64));
    let total_output_size = Arc::new(Mutex::new(0u64));
    let success_count = Arc::new(Mutex::new(0u32));
    let skipped_count = Arc::new(Mutex::new(0u32));
    let error_count = Arc::new(Mutex::new(0u32));

    let output_mutex = Arc::new(Mutex::new(()));

    let args = Arc::new(args);

    tasks.par_iter().for_each(|task| {
        let result = process_single_file(&task.input, &task.output, &args);

        let _lock = output_mutex.lock().unwrap();

        match &result {
            CompressionResult::Success { input_size, output_size } => {
                *total_input_size.lock().unwrap() += input_size;
                *total_output_size.lock().unwrap() += output_size;
                *success_count.lock().unwrap() += 1;

                if verbose >= 3 {
                    let diff = *output_size as i64 - *input_size as i64;
                    let pct = if *input_size > 0 { diff as f64 / *input_size as f64 * 100.0 } else { 0.0 };
                    let sign = if diff >= 0 { "+" } else { "-" };
                    println!("[Success] {} -> {}", task.input.display(), task.output.display());
                    println!("{} -> {} [{}{}  | {}{}%]\n",
                        format_size(*input_size),
                        format_size(*output_size),
                        sign,
                        format_size_diff(diff),
                        sign,
                        format!("{:.2}", pct.abs()),
                    );
                }
            }
            CompressionResult::Skipped { input_size, reason } => {
                *total_input_size.lock().unwrap() += input_size;
                *total_output_size.lock().unwrap() += input_size;
                *skipped_count.lock().unwrap() += 1;

                if verbose >= 2 {
                    println!("[Skipped] {} -> {}", task.input.display(), task.output.display());
                    println!("{} -> {} [-0 B | -0.00%]", format_size(*input_size), format_size(*input_size));
                    println!("{}\n", reason);
                }
            }
            CompressionResult::Error { message } => {
                *error_count.lock().unwrap() += 1;

                if verbose >= 2 {
                    eprintln!("[Error] {}: {}", task.input.display(), message);
                }
            }
        }
    });

    if verbose >= 1 {
        let total_in = *total_input_size.lock().unwrap();
        let total_out = *total_output_size.lock().unwrap();
        let success = *success_count.lock().unwrap();
        let skipped = *skipped_count.lock().unwrap();
        let errors = *error_count.lock().unwrap();
        let total_files = success + skipped + errors;

        let diff = total_out as i64 - total_in as i64;
        let pct = if total_in > 0 { diff as f64 / total_in as f64 * 100.0 } else { 0.0 };
        let sign = if diff >= 0 { "+" } else { "-" };

        println!("Compressed {} files ({} success, {} skipped, {} errors)", total_files, success, skipped, errors);
        println!("{} -> {} [{}{}  | {}{}%]",
            format_size(total_in),
            format_size(total_out),
            sign,
            format_size_diff(diff),
