#!/usr/bin/env python3
"""caesiumclt 1.3.0 - Image compression tool"""

import argparse
import os
import sys
import re
import math
import struct
import threading
import concurrent.futures
from pathlib import Path
from typing import Optional, List, Tuple

# Add workspace to path for lib module
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import src.lib as imglib

__version__ = "1.3.0"

SUPPORTED_EXTENSIONS = {'.jpg', '.jpeg', '.png', '.webp', '.gif'}

def format_size(n: int) -> str:
    if n >= 1024**3:
        return f"{n/(1024**3):.1f} GiB"
    elif n >= 1024**2:
        return f"{n/(1024**2):.1f} MiB"
    elif n >= 1024:
        return f"{n/1024:.1f} KiB"
    else:
        return f"{n} B"

def format_diff(d: int) -> str:
    a = abs(d)
    if a >= 1024**3:
        return f"{a/(1024**3):.1f} GiB"
    elif a >= 1024**2:
        return f"{a/(1024**2):.1f} MiB"
    elif a >= 1024:
        return f"{a/1024:.1f} KiB"
    else:
        return f"{a} B"

def parse_size(s: str) -> Optional[int]:
    s = s.strip()
    try:
        return int(s)
    except ValueError:
        pass
    m = re.match(r'^(\d+(?:\.\d+)?)\s*([KMGkmg]i[Bb]|[KMGkmg][Bb]|[KMGkmg])$', s)
    if m:
        num = float(m.group(1))
        unit = m.group(2).upper()
        if unit in ('KIB', 'KI'):
            return int(num * 1024)
        elif unit in ('MIB', 'MI'):
            return int(num * 1024**2)
        elif unit in ('GIB', 'GI'):
            return int(num * 1024**3)
        elif unit in ('KB', 'K'):
            return int(num * 1000)
        elif unit in ('MB', 'M'):
            return int(num * 1000**2)
        elif unit in ('GB', 'G'):
            return int(num * 1000**3)
    return None

def parse_min_savings(s: str):
    s = s.strip()
    if s.endswith('%'):
        try:
            return ('pct', float(s[:-1]))
        except ValueError:
            pass
    n = parse_size(s)
    if n is not None:
        return ('bytes', n)
    return None

def detect_format(data: bytes) -> str:
    if data[:2] == b'\xff\xd8':
        return 'jpeg'
    elif data[:8] == b'\x89PNG\r\n\x1a\n':
        return 'png'
    elif data[:4] == b'RIFF' and len(data) > 12 and data[8:12] == b'WEBP':
        return 'webp'
    elif data[:6] in (b'GIF87a', b'GIF89a'):
        return 'gif'
    return 'unknown'

def is_supported(path: str) -> bool:
    ext = Path(path).suffix.lower()
    return ext in SUPPORTED_EXTENSIONS

def collect_files(inputs: List[str], recursive: bool) -> List[str]:
    files = []
    for inp in inputs:
        p = Path(inp)
        if p.is_dir():
            if recursive:
                for root, dirs, fnames in os.walk(str(p)):
                    dirs.sort()
                    for f in sorted(fnames):
                        fp = os.path.join(root, f)
                        if is_supported(fp):
                            files.append(fp)
            else:
                for f in sorted(os.listdir(str(p))):
                    fp = os.path.join(str(p), f)
                    if os.path.isfile(fp) and is_supported(fp):
                        files.append(fp)
        elif p.is_file():
            if is_supported(str(p)):
                files.append(str(p))
    return files

def compute_base_path(files: List[str]) -> Optional[str]:
    if not files:
        return None
    if len(files) == 1:
        return str(Path(files[0]).parent)
    from os.path import commonpath
    try:
        return commonpath(files)
    except ValueError:
        return None

def get_output_ext(fmt: str, input_path: str) -> str:
    if fmt == 'jpeg':
        return 'jpg'
    elif fmt == 'png':
        return 'png'
    elif fmt == 'gif':
        return 'gif'
    elif fmt == 'webp':
        return 'webp'
    elif fmt == 'tiff':
        return 'tiff'
    else:
        return Path(input_path).suffix.lstrip('.')

def get_output_path(input_path: str, base_path: str, output_dir: Optional[str],
                    same_folder: bool, keep_structure: bool,
                    suffix: Optional[str], fmt: str) -> str:
    p = Path(input_path)
    stem = p.stem
    ext = get_output_ext(fmt, input_path)
    filename = f"{stem}{suffix or ''}.{ext}"
    if same_folder:
        return str(p.parent / filename)
    if output_dir:
        if keep_structure and base_path:
            try:
                rel = Path(input_path).parent.relative_to(base_path)
                return str(Path(output_dir) / rel / filename)
            except ValueError:
                pass
        return str(Path(output_dir) / filename)
    return filename

def compress_jpeg(pixels_rgba: bytes, width: int, height: int, quality: int,
                  lossless: bool, progressive: bool, chroma_sub: str,
                  exif_data: bytes = None) -> bytes:
    rgb = bytearray()
    for i in range(0, len(pixels_rgba), 4):
        rgb.extend(pixels_rgba[i:i+3])
    rgb = bytes(rgb)
    q = 100 if lossless else quality
    return imglib.encode_jpeg(rgb, width, height, q, progressive=progressive,
                               chroma_subsampling=chroma_sub, exif_data=exif_data)

def compress_png(pixels_rgba: bytes, width: int, height: int, quality: int,
                 lossless: bool, opt_level: int) -> bytes:
    if lossless:
        rgb = bytearray()
        for i in range(0, len(pixels_rgba), 4):
            rgb.extend(pixels_rgba[i:i+3])
        compression = min(9, max(0, opt_level + 3))
        return imglib.encode_png(bytes(rgb), width, height, 3, compression)
    else:
        max_colors = min(256, max(2, round(quality * 2.56)))
        return imglib.quantize_png(pixels_rgba, width, height, max_colors)

def compress_webp(pixels_rgba: bytes, width: int, height: int, quality: int,
                  lossless: bool) -> bytes:
    rgb = bytearray()
    for i in range(0, len(pixels_rgba), 4):
        rgb.extend(pixels_rgba[i:i+3])
    return imglib.encode_webp(bytes(rgb), width, height, float(quality), lossless=lossless)

def compress_gif(pixels_rgba: bytes, width: int, height: int, quality: int) -> bytes:
    return imglib.encode_gif(pixels_rgba, width, height, quality)

def compress_tiff(pixels_rgba: bytes, width: int, height: int) -> bytes:
    """Write uncompressed TIFF"""
    rgb = bytearray()
    for i in range(0, len(pixels_rgba), 4):
        rgb.extend(pixels_rgba[i:i+3])
    rgb = bytes(rgb)
    rows_per_strip = height
    strip_bytes = rgb
    strip_offset = 8 + 2 + 12 * 14 + 4  # header + ifd_count + entries + next_ifd
    # IFD entries we'll write
    image_width = width
    image_height = height
    bits_per_sample = 8
    samples_per_pixel = 3
    rows_per_strip_val = height
    strip_byte_count = len(strip_bytes)
    x_res_offset = strip_offset + strip_byte_count
    y_res_offset = x_res_offset + 8
    def short(v): return struct.pack('<H', v)
    def long_(v): return struct.pack('<I', v)
    def ifd_entry(tag, type_, count, value_or_offset):
        return struct.pack('<HHII', tag, type_, count, value_or_offset)
    header = b'II' + struct.pack('<H', 42) + struct.pack('<I', 8)
    n_entries = 14
    ifd_offset = 8
    entries = struct.pack('<H', n_entries)
    # SHORT=3, LONG=4, RATIONAL=5
    entries += ifd_entry(256, 4, 1, width)   # ImageWidth
    entries += ifd_entry(257, 4, 1, height)  # ImageLength
    entries += ifd_entry(258, 3, 1, 8)       # BitsPerSample=8
    entries += ifd_entry(259, 3, 1, 1)       # Compression=none
    entries += ifd_entry(262, 3, 1, 2)       # PhotometricInterpretation=RGB
    entries += ifd_entry(273, 4, 1, strip_offset)  # StripOffsets
    entries += ifd_entry(277, 3, 1, 3)       # SamplesPerPixel=3
    entries += ifd_entry(278, 4, 1, height)  # RowsPerStrip
    entries += ifd_entry(279, 4, 1, strip_byte_count)  # StripByteCounts
    entries += ifd_entry(282, 5, 1, x_res_offset)  # XResolution
    entries += ifd_entry(283, 5, 1, y_res_offset)  # YResolution
    entries += ifd_entry(284, 3, 1, 1)       # PlanarConfiguration=contiguous
    entries += ifd_entry(296, 3, 1, 2)       # ResolutionUnit=inch
    entries += ifd_entry(339, 3, 1, 1)       # SampleFormat=uint
    entries += struct.pack('<I', 0)  # Next IFD = 0
    resolution_data = struct.pack('<II', 72, 1) + struct.pack('<II', 72, 1)
    return header + entries + strip_bytes + resolution_data

def compress_image(data: bytes, input_path: str, fmt: str, quality: int,
                   lossless: bool, jpeg_baseline: bool, jpeg_chroma: str,
                   png_opt_level: int, keep_exif: bool, strip_icc: bool,
                   width: Optional[int], height: Optional[int],
                   long_edge: Optional[int], short_edge: Optional[int],
                   no_upscale: bool) -> bytes:
    """Decode, optionally resize, and re-encode an image"""
    in_fmt = detect_format(data)
    if in_fmt == 'unknown':
        raise ValueError(f"Unsupported input format")
    pixels_rgba, orig_w, orig_h = imglib.decode_image(data)
    new_w, new_h = compute_new_dimensions(orig_w, orig_h, width, height, long_edge, short_edge, no_upscale)
    if new_w != orig_w or new_h != orig_h:
        pixels_rgba = imglib.resize_image(pixels_rgba, orig_w, orig_h, new_w, new_h)
    exif_data = None
    if keep_exif and in_fmt == 'jpeg':
        exif_data = imglib._extract_exif(data)
    out_fmt = fmt if fmt != 'original' else in_fmt
    if out_fmt in ('jpeg', 'jpg'):
        return compress_jpeg(pixels_rgba, new_w, new_h, quality, lossless,
                              not jpeg_baseline, jpeg_chroma, exif_data)
    elif out_fmt == 'png':
        return compress_png(pixels_rgba, new_w, new_h, quality, lossless, png_opt_level)
    elif out_fmt == 'webp':
        return compress_webp(pixels_rgba, new_w, new_h, quality, lossless)
    elif out_fmt == 'gif':
        return compress_gif(pixels_rgba, new_w, new_h, quality)
    elif out_fmt == 'tiff':
        return compress_tiff(pixels_rgba, new_w, new_h)
    else:
        raise ValueError(f"Unsupported output format: {out_fmt}")

def compress_to_max_size(data: bytes, input_path: str, target_size: int,
                         fmt: str, jpeg_baseline: bool, jpeg_chroma: str,
                         png_opt_level: int, keep_exif: bool, strip_icc: bool,
                         width: Optional[int], height: Optional[int],
                         long_edge: Optional[int], short_edge: Optional[int],
                         no_upscale: bool) -> bytes:
    in_fmt = detect_format(data)
    if in_fmt == 'unknown':
        raise ValueError("Unsupported input format")
    pixels_rgba, orig_w, orig_h = imglib.decode_image(data)
    new_w, new_h = compute_new_dimensions(orig_w, orig_h, width, height, long_edge, short_edge, no_upscale)
    if new_w != orig_w or new_h != orig_h:
        pixels_rgba = imglib.resize_image(pixels_rgba, orig_w, orig_h, new_w, new_h)
    out_fmt = fmt if fmt != 'original' else in_fmt
    low, high = 1, 100
    best = b''
    while low <= high:
        mid = (low + high) // 2
        try:
            result = _encode_with_quality(pixels_rgba, new_w, new_h, out_fmt, mid,
                                           jpeg_baseline, jpeg_chroma, png_opt_level)
        except Exception:
            result = b''
        if len(result) <= target_size:
            best = result
            low = mid + 1
        else:
            high = mid - 1
    if not best:
        try:
            best = _encode_with_quality(pixels_rgba, new_w, new_h, out_fmt, 1,
                                         jpeg_baseline, jpeg_chroma, png_opt_level)
        except Exception:
            best = data
    return best

def _encode_with_quality(pixels_rgba, w, h, fmt, q, jpeg_baseline, jpeg_chroma, png_opt_level):
    if fmt in ('jpeg', 'jpg'):
        return compress_jpeg(pixels_rgba, w, h, q, False, not jpeg_baseline, jpeg_chroma)
    elif fmt == 'png':
        return compress_png(pixels_rgba, w, h, q, False, png_opt_level)
    elif fmt == 'webp':
        return compress_webp(pixels_rgba, w, h, q, False)
    elif fmt == 'gif':
        return compress_gif(pixels_rgba, w, h, q)
    else:
        return compress_jpeg(pixels_rgba, w, h, q, False, not jpeg_baseline, jpeg_chroma)

def compute_new_dimensions(orig_w, orig_h, width, height, long_edge, short_edge, no_upscale):
    if long_edge is not None:
        if orig_w >= orig_h:
            nw, nh = long_edge, max(1, round(long_edge * orig_h / orig_w))
        else:
            nw, nh = max(1, round(long_edge * orig_w / orig_h)), long_edge
    elif short_edge is not None:
        if orig_w <= orig_h:
            nw, nh = short_edge, max(1, round(short_edge * orig_h / orig_w))
        else:
            nw, nh = max(1, round(short_edge * orig_w / orig_h)), short_edge
    elif width is not None and height is not None:
        nw, nh = width, height
    elif width is not None:
        nw = width
        nh = max(1, round(width * orig_h / orig_w))
    elif height is not None:
        nh = height
        nw = max(1, round(height * orig_w / orig_h))
    else:
        return orig_w, orig_h
    if no_upscale:
        if nw > orig_w or nh > orig_h:
            return orig_w, orig_h
    return nw, nh

def process_file(input_path: str, output_path: str, args, print_lock) -> Tuple[str, int, int, str]:
    """Process a single file. Returns (status, input_size, output_size, message)"""
    try:
        data = open(input_path, 'rb').read()
    except Exception as e:
        return 'error', 0, 0, str(e)
    input_size = len(data)
    if detect_format(data) == 'unknown':
        return 'skip_silent', input_size, input_size, ''
    if not args.dry_run and os.path.exists(output_path):
        if args.overwrite == 'never':
            return 'skipped', input_size, input_size, 'File already exists, skipped due overwrite policy'
    try:
        if args.max_size:
            target = parse_size(args.max_size)
            if target is None:
                return 'error', input_size, 0, f"Invalid max-size: {args.max_size}"
            compressed = compress_to_max_size(
                data, input_path, target, args.format,
                args.jpeg_baseline, args.jpeg_chroma_subsampling,
                args.png_opt_level, args.exif, args.strip_icc,
                args.width, args.height, args.long_edge, args.short_edge, args.no_upscale
            )
        else:
            compressed = compress_image(
                data, input_path, args.format,
                args.quality if args.quality is not None else 80,
                args.lossless, args.jpeg_baseline, args.jpeg_chroma_subsampling,
                args.png_opt_level, args.exif, args.strip_icc,
                args.width, args.height, args.long_edge, args.short_edge, args.no_upscale
            )
    except Exception as e:
        return 'error', input_size, 0, str(e)
    output_size = len(compressed)
    if args.dry_run:
        return 'success', input_size, input_size, ''
    if os.path.exists(output_path):
        if args.overwrite == 'bigger':
            existing_size = os.path.getsize(output_path)
            if existing_size <= output_size:
                return 'skipped', input_size, input_size, 'File already exists, skipped due overwrite policy'
    if args.min_savings:
        ms = parse_min_savings(args.min_savings)
        if ms:
            kind, threshold = ms
            if kind == 'pct':
                actual_pct = (input_size - output_size) / input_size * 100.0 if input_size > 0 else 0.0
                if actual_pct < threshold:
                    reason = f"Insufficient savings: {actual_pct:.2f}% < {threshold:.2f}%, skipped"
                    return 'skipped', input_size, input_size, reason
            else:
                savings = input_size - output_size if input_size >= output_size else 0
                if savings < threshold:
                    reason = f"Insufficient savings: {format_size(savings)} < {format_size(threshold)}, skipped"
                    return 'skipped', input_size, input_size, reason
    try:
        os.makedirs(os.path.dirname(output_path), exist_ok=True) if os.path.dirname(output_path) else None
        with open(output_path, 'wb') as f:
            f.write(compressed)
    except Exception as e:
        return 'error', input_size, 0, str(e)
    if args.keep_dates:
        try:
            stat = os.stat(input_path)
            os.utime(output_path, (stat.st_atime, stat.st_mtime))
        except Exception:
            pass
    return 'success', input_size, output_size, ''

def main():
    parser = argparse.ArgumentParser(
        prog='caesiumclt',
        description='A fast and efficient lossy and/or lossless image compression tool',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument('files', nargs='*', metavar='FILES', help='Input files or directories to process')
    comp_group = parser.add_mutually_exclusive_group(required=True)
    comp_group.add_argument('-q', '--quality', type=int, metavar='QUALITY',
                             help='Compression quality [0-100], higher values mean better quality')
    comp_group.add_argument('--lossless', action='store_true',
                             help='Use lossless compression (may increase file size for some formats)')
    comp_group.add_argument('--max-size', metavar='MAX_SIZE',
                             help='Target maximum file size in bytes or human-readable format (e.g., 100KB, 0.5MB)')
    dest_group = parser.add_mutually_exclusive_group(required=True)
    dest_group.add_argument('-o', '--output', metavar='OUTPUT', help='Output directory path')
    dest_group.add_argument('--same-folder-as-input', action='store_true',
                             help="Use input file's directory as output (WARNING: may overwrite originals)")
    parser.add_argument('--width', type=int, help='Output image width in pixels (preserves the aspect ratio if height not set)')
    parser.add_argument('--height', type=int, help='Output image height in pixels (preserves the aspect ratio if width not set)')
    parser.add_argument('--long-edge', type=int, dest='long_edge', help='Size in pixels for the longest edge of the image')
    parser.add_argument('--short-edge', type=int, dest='short_edge', help='Size in pixels for the shortest edge of the image')
    parser.add_argument('--no-upscale', action='store_true', dest='no_upscale', help='Prevents upscaling of the image when resizing')
    parser.add_argument('--format', default='original',
                         choices=['jpeg', 'png', 'gif', 'webp', 'tiff', 'original'],
                         help='Convert to the selected output format or keep the original\n\n[default: original]\n[possible values: jpeg, png, gif, webp, tiff, original]')
    parser.add_argument('--png-opt-level', type=int, default=3, dest='png_opt_level',
                         metavar='PNG_OPT_LEVEL',
                         help='PNG optimization level [0-6], higher values provide better compression\n\n[default: 3]')
    parser.add_argument('--jpeg-chroma-subsampling', default='auto',
                         dest='jpeg_chroma_subsampling',
                         choices=['4:4:4', '4:2:2', '4:2:0', '4:1:1', 'auto'],
                         metavar='JPEG_CHROMA_SUBSAMPLING',
                         help='Chroma subsampling for JPEG files\n\n[default: auto]\n[possible values: 4:4:4, 4:2:2, 4:2:0, 4:1:1, auto]')
    parser.add_argument('--jpeg-baseline', action='store_true', dest='jpeg_baseline',
                         help='Output baseline JPEG instead of progressive (default)')
    parser.add_argument('--zopfli', action='store_true', help='Use zopfli for PNG optimization (significantly slower but better compression)')
    parser.add_argument('-e', '--exif', action='store_true', help='Keep EXIF metadata during compression')
    parser.add_argument('--keep-dates', action='store_true', dest='keep_dates', help='Preserve original file timestamps')
    parser.add_argument('--strip-icc', action='store_true', dest='strip_icc', help='Strips ICC profile info on JPG files, ignoring the -e flag')
    parser.add_argument('--suffix', help='Add suffix to output filenames')
    parser.add_argument('-R', '--recursive', action='store_true', help='Scan subfolders recursively when input is a directory')
    parser.add_argument('-S', '--keep-structure', action='store_true', dest='keep_structure',
                         help='Preserve directory structure (requires -R/--recursive)')
    parser.add_argument('-d', '--dry-run', action='store_true', dest='dry_run',
                         help='Simulate compression without writing files')
    parser.add_argument('--threads', type=int, default=0,
                         help='Number of parallel jobs (0 = auto-detect, max = available processors)\n\n[default: 0]')
    parser.add_argument('-O', '--overwrite', default='all',
                         choices=['all', 'never', 'bigger'],
                         help='Policy for handling existing output files\n\nPossible values:\n- all:    Always overwrite existing files\n- never:  Never overwrite existing files\n- bigger: Overwrite only if the existing file is bigger\n\n[default: all]')
    parser.add_argument('--min-savings', dest='min_savings', metavar='MIN_SAVINGS',
                         help="Minimum compression savings required to write an output file. Use percentage (e.g., '10%%', '1.5%%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes")
    parser.add_argument('-Q', '--quiet', action='store_true', help='Suppress all output')
    parser.add_argument('--verbose', type=int, default=1,
                         help='Verbosity level: 0 = quiet, 1 = progress only, 2 = errors only, 3 = all\n\n[default: 1]')
    parser.add_argument('-V', '--version', action='version', version=f'caesiumclt {__version__}')

    args = parser.parse_args()
    verbose = 0 if args.quiet else args.verbose
    if not args.files:
        parser.error("at least one file or directory is required")
    files = collect_files(args.files, args.recursive)
    if not files:
        print("Unable to compute the base path for the files.", file=sys.stderr)
        sys.exit(255)
    base_path = compute_base_path(files)
    if base_path is None:
        print("Unable to compute the base path for the files.", file=sys.stderr)
        sys.exit(255)
    tasks = []
    for f in files:
        out = get_output_path(f, base_path, args.output, args.same_folder_as_input,
                               args.keep_structure, args.suffix, args.format)
        tasks.append((f, out))
    total_in = 0
    total_out = 0
    n_success = 0
    n_skipped = 0
    n_error = 0
    lock = threading.Lock()
    print_lock = threading.Lock()

    def do_task(inp, out):
        nonlocal total_in, total_out, n_success, n_skipped, n_error
        status, isz, osz, msg = process_file(inp, out, args, print_lock)
        with lock:
            if status == 'success':
                total_in += isz
                total_out += osz
                n_success += 1
                if verbose >= 3:
                    diff = osz - isz
                    pct = diff / isz * 100.0 if isz > 0 else 0.0
                    sign = '+' if diff >= 0 else '-'
                    with print_lock:
                        print(f"[Success] {inp} -> {out}")
                        print(f"{format_size(isz)} -> {format_size(osz)} [{sign}{format_diff(diff)} | {sign}{abs(pct):.2f}%]")
                        print()
            elif status == 'skipped':
                total_in += isz
                total_out += isz
                n_skipped += 1
                if verbose >= 2:
                    with print_lock:
                        print(f"[Skipped] {inp} -> {out}")
                        print(f"{format_size(isz)} -> {format_size(isz)} [-0 B | -0.00%]")
                        print(msg)
                        print()
            elif status == 'skip_silent':
                pass
            else:
                n_error += 1
                if verbose >= 2:
                    with print_lock:
                        print(f"[Error] {inp}: {msg}", file=sys.stderr)

    n_threads = args.threads if args.threads > 0 else min(32, os.cpu_count() or 1)
    if n_threads == 1:
        for inp, out in tasks:
            do_task(inp, out)
    else:
        with concurrent.futures.ThreadPoolExecutor(max_workers=n_threads) as executor:
            futures = [executor.submit(do_task, inp, out) for inp, out in tasks]
            for f in concurrent.futures.as_completed(futures):
                pass

    if verbose >= 1:
        total_files = n_success + n_skipped + n_error
        diff = total_out - total_in
        pct = diff / total_in * 100.0 if total_in > 0 else 0.0
        sign = '+' if diff >= 0 else '-'
        print(f"Compressed {total_files} files ({n_success} success, {n_skipped} skipped, {n_error} errors)")
        print(f"{format_size(total_in)} -> {format_size(total_out)} [{sign}{format_diff(diff)} | {sign}{abs(pct):.2f}%]")

if __name__ == '__main__':
    main()
